import { existsSync } from 'node:fs'
import path from 'node:path'

/**
 * Runtime configuration, read from the environment (12-factor).
 *
 * Every pointer to a backing service (database, Temporal) and every port is
 * configured here, so several checkouts of this repo (e.g. git worktrees) can
 * run side by side without colliding. See docs/adr/0001-per-worktree-runtime-config.md.
 *
 * In development the values come from `backend/.env` (generated by
 * `scripts/worktree-setup.sh`, documented in `backend/.env.example`). Variables
 * already set in the process environment take precedence over the file.
 */

const envFile = path.resolve(__dirname, '..', '.env')
if (existsSync(envFile)) {
  process.loadEnvFile(envFile)
}

function required(name: string): string {
  const value = process.env[name]?.trim()
  if (!value) {
    throw new Error(
      `Missing required environment variable ${name}. ` +
        'Run scripts/worktree-setup.sh or copy backend/.env.example to backend/.env.',
    )
  }
  return value
}

function port(name: string): number {
  const raw = required(name)
  const value = Number(raw)
  if (!Number.isInteger(value) || value < 1 || value > 65535) {
    throw new Error(`Environment variable ${name} must be a valid TCP port, got "${raw}"`)
  }
  return value
}

export const config = {
  port: port('PORT'),
  // Read by Prisma itself (schema.prisma); validated here so the API fails fast.
  databaseUrl: required('DATABASE_URL'),
  temporal: {
    address: required('TEMPORAL_ADDRESS'),
    // No defaults on purpose: falling back to the shared `default` namespace
    // would let workers from different checkouts steal each other's tasks.
    namespace: required('TEMPORAL_NAMESPACE'),
    taskQueue: required('TEMPORAL_TASK_QUEUE'),
  },
} as const
